<script>
const filterWeights=()=>{const input=document.querySelector('[data-filter-table]');document.querySelectorAll('#pesos-table tbody tr').forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase().includes(input.value.toLocaleLowerCase())||(document.getElementById('pesos-pendentes').checked&&row.querySelector('input[type="number"]').value!==''));};
document.querySelector('[data-filter-table]')?.addEventListener('input',filterWeights);document.getElementById('pesos-pendentes')?.addEventListener('change',filterWeights);
document.getElementById('sugerir-metas')?.addEventListener('click',()=>{if(!confirm('Preencher sugestão linear somente para revisão?'))return;const fields=Array.from(document.querySelectorAll('[data-meta-date]'));const first=Date.parse(fields[0]?.dataset.metaDate),last=Date.parse(fields.at(-1)?.dataset.metaDate);fields.forEach(f=>f.value=last===first?100:((Date.parse(f.dataset.metaDate)-first)/(last-first)*100).toFixed(2));});
document.querySelectorAll('.evolucao-version-form').forEach(form=>form.addEventListener('submit',event=>{
    if(!confirm('Confirma uma nova versão com estes valores?')){event.preventDefault();return;}
    const values={};form.querySelectorAll('input[name^="valores["]').forEach(input=>{const key=input.name.slice(8,-1);values[key]=input.value;input.disabled=true;});
    const payload=document.createElement('input');payload.type='hidden';payload.name='valores_json';payload.value=JSON.stringify(values);form.appendChild(payload);
}));
</script>
